/// <summary>
/// This is a service class
/// CB355_DutyRoll
/// </summary>
class METDutyRollMonthlyService extends SysOperationServiceBase
{
    List                itemList;
    List                siteList;
    boolean             adHoc;
    boolean             runForExcise;
    RecordInsertList    recordInsertList;
    TransDate           startDate;


}

Method.Source:
    /// <summary>
    /// main process method
    /// </summary>
    /// <param name = "_dataContract">Contract</param>
    public void processOperation(METDutyRollMonthlyContract _dataContract)
    {
        BatchHeader batchHeader;

        try
        {
            batchHeader     = this.getCurrentBatchHeader();
            
            if (batchHeader == null)
            {
                batchHeader = batchHeader::construct();
            }
            batchHeader.parmCaption("@MET:MonthlyDutyRoll");

            itemList        = _dataContract.parmItemList();
            siteList        = _dataContract.parmSiteList();
            adHoc           = _dataContract.parmAdHoc();
            runForExcise    = _dataContract.parmRunForExcise();

            recordInsertList    = new RecordInsertList(tableNum(METDutyRollValuesLine));

            startDate   = this.getFstMonday();

            this.processSites();
 
            //NS - Created for the CB799 - to provide the extract of duty per case value after the batch job is finished.
            if (BusinessEventsConfigurationReader::isBusinessEventEnabled(classStr(METDutyRollMonthlyBusinessEvents)))
            {
                METDutyRollMonthlyBusinessEvents::newFromDutyRollMonthly(_dataContract).send();
            }
            else
            {
                throw error("@MET:DutyRollExtBusinessEventNotEnabled");
            }
        }
        catch
        {
            error ("@WAX:UpdateCancelled");
        }
        //NE - Created for the CB799 - to provide the extract of duty per case value after the batch job is finished.
    }

    /// <summary>
    /// process selected/all sited
    /// </summary>
    private void processSites()
    {
        InventSite      inventSite;
        InventSiteId    siteId;

        if (!siteList.empty())
        {
            ListEnumerator iter = siteList.getEnumerator();

            while (iter.moveNext())
            {
                siteId  = iter.current();
                this.processSite(siteId);
            }
        }
        else
        {
            while select inventSite
                where inventSite.METBondedWarehouse == NoYes::Yes
            {
                this.processSite(inventSite.SiteId);
            }
        }
    }

    /// <summary>
    /// process one sited
    /// </summary>
    /// <param name = "_siteId">InventSiteId</param>
    private void processSite(InventSiteId   _siteId)
    {
        METDutyRollValuesTable  dutyRollValuesTable;
        dutyRollValuesTable = METDutyRollValuesTable::findActive(_siteId);
        try
        {
            if (adHoc)
            {
                if (dutyRollValuesTable.RecId)
                {
                    this.processItems(_siteId, dutyRollValuesTable.RecId);
                    recordInsertList.insertDatabase();
                }
            }
            else
            {
                if (dutyRollValuesTable.RecId)
                {
                    ttsbegin;
                    dutyRollValuesTable.selectForUpdate(true);
                    dutyRollValuesTable.inactivateRecord();
                    dutyRollValuesTable.update();
                    ttscommit;
                }
                dutyRollValuesTable.clear();
                dutyRollValuesTable.Site = _siteId;
                dutyRollValuesTable.StartDate = startDate;
                dutyRollValuesTable.Status = METDutyRollStatus::Active;
                dutyRollValuesTable.insert();

                this.processItems(_siteId, dutyRollValuesTable.RecId);

                recordInsertList.insertDatabase();
            }
        }
        catch (Exception::Error)
        {
            error("@SYS93289");
            exceptionTextFallThrough();
        }
    }

    /// <summary>
    /// process selected/all items
    /// </summary>
    /// <param name = "_siteId">InventSiteId</param>
    /// <param name = "_refRecId">RefRecId</param>
    private void processItems(InventSiteId  _siteId, RefRecId   _refRecId)
    {
        const   str             tariffCodeC = "@MET:TariffCodeC";
        const   str             tariffCodeE = "@MET:TariffCodeE";
        QueryRun                queryRunItem;
        Query                   query;
        QueryBuildDataSource    metTariffItemCodeQbds;
        QueryBuildRange         qbr;
        InventTable             inventTable;
        ItemId                  itemId;

        if (!itemList.empty())
        {
            ListEnumerator iter = itemList.getEnumerator();

            while (iter.moveNext())
            {
                itemId  = iter.current();
                this.processItem(_siteId, itemId, _refRecId);
            }
        }
        else
        {
            query = new Query(queryStr(METInventTableTariffItemCode));
            if (!adHoc && !runForExcise)
            {
                metTariffItemCodeQbds = query.dataSourceTable(tableNum(METTariffItemCodeBase));
                qbr = metTariffItemCodeQbds.addRange(fieldNum(METTariffItemCodeBase, CustomsExcise));
                qbr.value(queryValue(tariffCodeC));
            }
            else
            if(runForExcise)
            {
                metTariffItemCodeQbds = query.dataSourceTable(tableNum(METTariffItemCodeBase));
                qbr = metTariffItemCodeQbds.addRange(fieldNum(METTariffItemCodeBase, CustomsExcise));
                qbr.value(queryValue(tariffCodeE));
            }
            
            queryRunItem = new QueryRun(query);
            while (queryRunItem.next())
            {
                inventTable = queryRunItem.get(tableNum(InventTable));
                this.processItem(_siteId, inventTable.ItemId, _refRecId);
            }
        }
    }

    /// <summary>
    /// process one item
    /// </summary>
    /// <param name = "_siteId">InventSiteId</param>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_refRecId">RefRecId</param>
    private void processItem(InventSiteId  _siteId, ItemId  _itemId, RefRecId   _refRecId)
    {
        METDutyRollValuesLine       dutyRollValuesLine;
        InventTable                 inventTable = InventTable::find(_itemId);
        METInventTable              metInventTable = METInventTable::find(_itemId);
        METTariffItemCode           tariffItemCode;
        METExciseSiteDutySetup      exciseSiteDutySetup;
        Qty                         lalqty;
        Qty                         averageQty;
        container                   con;

        dutyRollValuesLine.clear();
        dutyRollValuesLine.CalcDate     = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
        dutyRollValuesLine.RefRecId     = _refRecId;
        dutyRollValuesLine.Site         = _siteId;
        dutyRollValuesLine.ItemId       = _itemId;
        dutyRollValuesLine.ItemName     = inventTable.NameAlias;
        dutyRollValuesLine.Unit         = inventTable.salesUnitId();
        [dutyRollValuesLine.AverageVFD,averageQty] = this.calcAvgDutyCase(_itemId, _siteId);
        tariffItemCode                  = METTariffItemCode::findRecId(metInventTable.METTariffItemCodeBaseRecid);
        //Duty amount = (pack size * Bottlesize * (AlcStrn/100) * Duty-LAL) + (VFD * (Adval Rate/100))
        dutyRollValuesLine.TotalDutyPerCase = metInventTable.ItemPack * metInventTable.BottleSize * (metInventTable.AlcoholContent/100) * tariffItemCode.DutyLAL + (dutyRollValuesLine.AverageVFD * tariffItemCode.AdValoremOrBeerSubsidyRate/100);

        if(runForExcise)
        {
            exciseSiteDutySetup = METExciseSiteDutySetup::find(_siteId, _itemId, true);
            if (exciseSiteDutySetup.RecId)
            {
                // LAL = Alcohol Content (%) x Bottle Size (L) x Quantity (each)
                lalqty = (metInventTable.AlcoholContent / 100) * metInventTable.BottleSize * averageQty;
                exciseSiteDutySetup.ExcisePerCase   = tariffItemCode.DutyLAL * lalqty;
                exciseSiteDutySetup.ValidFrom       = startDate;
                exciseSiteDutySetup.update();
            }

        }
        recordInsertList.add(dutyRollValuesLine);
    }

    /// <summary>
    /// calculate date for the first monday of the next month
    /// </summary>
    /// <returns>TransDate</returns>
    private TransDate getFstMonday()
    {
        TransDate   transDate;
        int         day;
        int         daysToAdd;

        transDate   = dateMthFwd(DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone()), 1);
        //1st day if the next month
        transDate   = mkDate(1, mthOfYr(transDate), Year(transDate));
        //day of the week on the 1st day on the next month
        day         = dayOfWk(transDate);
        //count days to the next Monday
        daysToAdd   = 8 - day;
        //1st Monday of the next month
        transDate   = transDate + daysToAdd;

        return transDate;
    }

    /// <summary>
    /// calculate average VFD and average inventory quantity
    /// </summary>
    /// <param name = "_itemId">ItemId</param>
    /// <param name = "_siteId">InventSiteId</param>
    /// <returns>container</returns>
    private container calcAvgDutyCase(ItemId   _itemId, InventSiteId   _siteId)
    {
        METValueForDuty avgDuty;
        METExciseInformationTable   exciseInformationTable;
        METExciseSiteDutySetup      exciseSiteDutySetup;
        PurchLine                   purchLine;
        TransDateTime               startDateTime;
        TransDateTime               endDateTime;
        TransDate                   transDate;
        int                         countRecords;
        Qty                         qty;

        transDate = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());
        endDateTime = DateTimeUtil::addSeconds(DateTimeUtil::newDateTime(transDate+1, 0), - 1);
        transDate = mkDate(1, mthOfYr(transDate), year(transDate));
        startDateTime = DateTimeUtil::newDateTime(transDate, 0);

        while select exciseInformationTable
            where exciseInformationTable.InventTransType == InventTransType::Purch
                && exciseInformationTable.ItemId == _itemId
                && exciseInformationTable.SiteId == _siteId
            exists join purchLine
                where purchLine.InventTransId == exciseInformationTable.InventTransId
                    && purchLine.CreatedDateTime >= startDateTime
                    && purchLine.CreatedDateTime <= endDateTime
        {
            countRecords++;
            if (countRecords <= 10)
            {
                qty = qty + exciseInformationTable.InventoryQty;

                select firstonly ValueForDuty from exciseSiteDutySetup
                where exciseSiteDutySetup.ItemId == _itemId      
                    && exciseSiteDutySetup.SiteId == _siteId;
                avgDuty = avgDuty + exciseSiteDutySetup.ValueForDuty;
            }
            else
            {
                avgDuty = avgDuty/(countRecords-1);
                qty     = qty/(countRecords-1);
                return [avgDuty, qty];
            }
        }
        if (countRecords)
        {
            avgDuty = avgDuty/countRecords;
            qty     = qty/countRecords;
        }
        
        return [avgDuty, qty];
    }
